   * @param emergency_state method that will be called with the value of the outgoing data
   *        port 'emergency_state'.
   * @param next_recovery_state method that will be called with the value of the outgoing data
   *        port 'next_recovery_state'.
   */
  def check_concrete_output(gate_mining: Mining_Threat_Retreat_Supervision.RecoveryGateValue => B,
                            gate_defense: Mining_Threat_Retreat_Supervision.RecoveryGateValue => B,
                            gate_mobility: Mining_Threat_Retreat_Supervision.RecoveryGateValue => B,
                            emergency_state: Mining_Threat_Retreat_Supervision.EmergencyStateValue => B,
                            next_recovery_state: Mining_Threat_Retreat_Supervision.RecoveryStateValue => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val gate_miningValue: Mining_Threat_Retreat_Supervision.RecoveryGateValue = get_gate_mining().get
    if(!gate_mining(gate_miningValue)) {
      testFailures = testFailures :+ st"'gate_mining' did not match expected: value of the outgoing data port is ${gate_miningValue}"
    }
    val gate_defenseValue: Mining_Threat_Retreat_Supervision.RecoveryGateValue = get_gate_defense().get
    if(!gate_defense(gate_defenseValue)) {
      testFailures = testFailures :+ st"'gate_defense' did not match expected: value of the outgoing data port is ${gate_defenseValue}"
    }
    val gate_mobilityValue: Mining_Threat_Retreat_Supervision.RecoveryGateValue = get_gate_mobility().get
    if(!gate_mobility(gate_mobilityValue)) {
      testFailures = testFailures :+ st"'gate_mobility' did not match expected: value of the outgoing data port is ${gate_mobilityValue}"
    }
    val emergency_stateValue: Mining_Threat_Retreat_Supervision.EmergencyStateValue = get_emergency_state().get
    if(!emergency_state(emergency_stateValue)) {
      testFailures = testFailures :+ st"'emergency_state' did not match expected: value of the outgoing data port is ${emergency_stateValue}"
    }
    val next_recovery_stateValue: Mining_Threat_Retreat_Supervision.RecoveryStateValue = get_next_recovery_state().get
    if(!next_recovery_state(next_recovery_stateValue)) {
      testFailures = testFailures :+ st"'next_recovery_state' did not match expected: value of the outgoing data port is ${next_recovery_stateValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


